<?php require __DIR__.'/../config/config.php';require_role('admin');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('INSERT INTO announcements(title,body) VALUES(?,?)')->execute([trim($_POST['title']),trim($_POST['body'])]);redirect('announcements.php');}$rows=$pdo->query('SELECT * FROM announcements ORDER BY id DESC')->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>الإعلانات</title><link rel="stylesheet" href="../assets/style.css"></head><body><main class="container section"><a href="./">← لوحة المدير</a><div class="card"><h1>الإعلانات</h1><form method="post"><div class="field"><label>العنوان</label><input name="title" required></div><div class="field"><label>النص</label><textarea name="body" required></textarea></div><button class="btn">نشر الإعلان</button></form></div><div class="section"><?php foreach($rows as $r):?><div class="card" style="margin:10px 0"><h3><?=e($r['title'])?></h3><p><?=nl2br(e($r['body']))?></p></div><?php endforeach;?></div></main></body></html>
